#include <bits/stdc++.h>
using namespace std;

struct Edge { int to, rev; int cap; };
vector<Edge> graph[205];
int level[205], iter[205];

void add_edge(int from, int to, int cap) {
    graph[from].push_back({to, (int)graph[to].size(), cap});
    graph[to].push_back({from, (int)graph[from].size()-1, cap});
}

bool bfs(int s, int t, int n) {
    fill(level, level+n+1, -1);
    queue<int> q;
    level[s] = 0; q.push(s);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (auto& e : graph[v]) if (e.cap > 0 && level[e.to] < 0) { level[e.to] = level[v]+1; q.push(e.to); }
    }
    return level[t] >= 0;
}

int dfs(int v, int t, int f) {
    if (v == t) return f;
    for (int& i = iter[v]; i < (int)graph[v].size(); i++) {
        Edge& e = graph[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            int d = dfs(e.to, t, min(f, e.cap));
            if (d > 0) { e.cap -= d; graph[e.to][e.rev].cap += d; return d; }
        }
    }
    return 0;
}

int max_flow(int s, int t, int n) {
    int flow = 0;
    while (bfs(s, t, n)) {
        fill(iter, iter+n+1, 0);
        int d;
        while ((d = dfs(s, t, INT_MAX)) > 0) flow += d;
    }
    return flow;
}

