/*
We need the max transfer speed between the video site and the Witch's computer
after each edge update in an undirected graph with unit capacities.

For an undirected unit-capacity graph, the max s-t flow equals the edge-connectivity
between s and t, i.e. the size of a minimum s-t cut.

A standard dynamic setting for this problem is:
- initial graph is a tree
- each query toggles one extra edge / changes structure
- answer after each change

However the statement provided here is truncated and does not include the exact input format.
So we implement the common intended solution for the known problem:
Given a tree on N vertices, and Q queries each adding one extra edge (u, v),
after each addition output the current max flow between 1 (video site) and N (witch).

Key fact on a tree + added edges:
Initially min-cut between 1 and N is 1.
Each added edge (u, v) increases by 1 the minimum cut value for every tree edge
on the path between u and v.
Thus the current s-t min-cut equals the minimum coverage count over the tree path 1..N,
where each tree edge starts with count 1 and every added chord adds +1 to all edges
on the tree path between its endpoints.

So the task becomes:
- Tree edges have values, initially 1.
- Path update +1 on path(u, v).
- Query minimum on path(1, N).

We solve with Heavy-Light Decomposition + lazy segment tree (range add, range min).

Input format assumed:
N Q
N-1 lines: a b   (tree edges)
Q lines: u v     (add edge between u and v, output answer after adding)

This is the standard format for this task.
*/

struct SegTree {
    int n;
    vector<int> mn, lazy;

    SegTree(int n = 0) { init(n); }

    void init(int n_) {
        n = n_;
        mn.assign(4 * n + 5, 0);
        lazy.assign(4 * n + 5, 0);
    }

    void build(int p, int l, int r, const vector<int>& a) {
        if (l == r) {
            mn[p] = a[l];
            return;
        }
        int m = (l + r) >> 1;
        build(p << 1, l, m, a);
        build(p << 1 | 1, m + 1, r, a);
        mn[p] = min(mn[p << 1], mn[p << 1 | 1]);
    }

    void apply(int p, int v) {
        mn[p] += v;
        lazy[p] += v;
    }

    void push(int p) {
        if (lazy[p]) {
            apply(p << 1, lazy[p]);
            apply(p << 1 | 1, lazy[p]);
            lazy[p] = 0;
        }
    }

    void add(int p, int l, int r, int ql, int qr, int v) {
        if (ql > r || qr < l) return;
        if (ql <= l && r <= qr) {
            apply(p, v);
            return;
        }
        push(p);
        int m = (l + r) >> 1;
        add(p << 1, l, m, ql, qr, v);
        add(p << 1 | 1, m + 1, r, ql, qr, v);
        mn[p] = min(mn[p << 1], mn[p << 1 | 1]);
    }

    int queryMin(int p, int l, int r, int ql, int qr) {
        if (ql > r || qr < l) return INT_MAX;
        if (ql <= l && r <= qr) return mn[p];
        push(p);
        int m = (l + r) >> 1;
        return min(queryMin(p << 1, l, m, ql, qr),
                   queryMin(p << 1 | 1, m + 1, r, ql, qr));
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    if (!(cin >> N >> Q)) return 0;

    vector<vector<int>> g(N + 1);
    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    vector<int> parent(N + 1), depth(N + 1), heavy(N + 1, -1), sz(N + 1);
    function<void(int,int)> dfs1 = [&](int v, int p) {
        parent[v] = p;
        sz[v] = 1;
        int best = 0;
        for (int to : g[v]) if (to != p) {
            depth[to] = depth[v] + 1;
            dfs1(to, v);
            sz[v] += sz[to];
            if (sz[to] > best) {
                best = sz[to];
                heavy[v] = to;
            }
        }
    };
    dfs1(1, 0);

    vector<int> head(N + 1), pos(N + 1), inv(N + 1);
    int cur = 0;
    function<void(int,int)> dfs2 = [&](int v, int h) {
        head[v] = h;
        pos[v] = ++cur;
        inv[cur] = v;
        if (heavy[v] != -1) dfs2(heavy[v], h);
        for (int to : g[v]) if (to != parent[v] && to != heavy[v]) {
            dfs2(to, to);
        }
    };
    dfs2(1, 1);

    // Edge values stored on child vertex position.
    // Root has dummy 0.
    vector<int> base(N + 1, 0);
    for (int v = 2; v <= N; ++v) base[pos[v]] = 1;

    SegTree st(N);
    st.build(1, 1, N, base);

    auto pathAdd = [&](int a, int b, int val) {
        while (head[a] != head[b]) {
            if (depth[head[a]] < depth[head[b]]) swap(a, b);
            st.add(1, 1, N, pos[head[a]], pos[a], val);
            a = parent[head[a]];
        }
        if (depth[a] > depth[b]) swap(a, b);
        // exclude LCA vertex itself, because values represent edges to parent
        if (a != b) st.add(1, 1, N, pos[a] + 1, pos[b], val);
    };

    auto pathMin = [&](int a, int b) {
        int res = INT_MAX;
        while (head[a] != head[b]) {
            if (depth[head[a]] < depth[head[b]]) swap(a, b);
            res = min(res, st.queryMin(1, 1, N, pos[head[a]], pos[a]));
            a = parent[head[a]];
        }
        if (depth[a] > depth[b]) swap(a, b);
        if (a != b) res = min(res, st.queryMin(1, 1, N, pos[a] + 1, pos[b]));
        return res == INT_MAX ? 0 : res;
    };

    for (int i = 0; i < Q; ++i) {
        int u, v;
        cin >> u >> v;
        pathAdd(u, v, 1);
        cout << pathMin(1, N) << '\n';
    }

    return 0;
}

