    for (int i = 0; i < N; i++) {
        nodes[i].parent = i;
        nodes[i].size = 1;
        nodes[i].comp_min = i;
        nodes[i].comp_max = i;
    }
}

int find(int x) {
    if (nodes[x].parent != x) {
        nodes[x].parent = find(nodes[x].parent);
    }
    return nodes[x].parent;
}

void union_sets(int a, int b) {
    int ra = find(a);
    int rb = find(b);
    if (ra == rb) return;
    if (nodes[ra].size < nodes[rb].size) {
        int temp = ra;
        ra = rb;
        rb = temp;
    }
    nodes[rb].parent = ra;
    nodes[ra].size += nodes[rb].size;
    if (nodes[rb].comp_min < nodes[ra].comp_min)
        nodes[ra].comp_min = nodes[rb].comp_min;
    if (nodes[rb].comp_max > nodes[ra].comp_max)
        nodes[ra].comp_max = nodes[rb].comp_max;
}

