typedef struct {
    int to, cap, rev;
} Edge;

typedef struct {
    Edge *e;
    int sz, cap;
} Vec;

static void vec_push(Vec *v, Edge x) {
    if (v->sz == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 4;
        v->e = (Edge*)realloc(v->e, sizeof(Edge) * v->cap);
    }
    v->e[v->sz++] = x;
}

typedef struct {
    int n;
    Vec *g;
    int *level;
    int *it;
} Dinic;

static void dinic_init(Dinic *D, int n) {
    D->n = n;
    D->g = (Vec*)calloc(n + 1, sizeof(Vec));
    D->level = (int*)malloc((n + 1) * sizeof(int));
    D->it = (int*)malloc((n + 1) * sizeof(int));
}

static void dinic_clear(Dinic *D) {
    for (int i = 0; i <= D->n; i++) free(D->g[i].e);
    free(D->g);
    free(D->level);
    free(D->it);
}

static void add_dir(Dinic *D, int u, int v, int c) {
    Edge a = {v, c, D->g[v].sz};
    Edge b = {u, 0, D->g[u].sz};
    vec_push(&D->g[u], a);
    vec_push(&D->g[v], b);
}

static void add_undir_unit(Dinic *D, int u, int v) {
    /* undirected edge of capacity 1 = two directed edges capacity 1 */
    add_dir(D, u, v, 1);
    add_dir(D, v, u, 1);
}

static int bfs(Dinic *D, int s, int t) {
    for (int i = 1; i <= D->n; i++) D->level[i] = -1;
    int *q = (int*)malloc((D->n + 5) * sizeof(int));
    int head = 0, tail = 0;
    D->level[s] = 0;
    q[tail++] = s;
    while (head < tail) {
        int u = q[head++];
        for (int i = 0; i < D->g[u].sz; i++) {
            Edge *e = &D->g[u].e[i];
            if (e->cap > 0 && D->level[e->to] < 0) {
                D->level[e->to] = D->level[u] + 1;
                q[tail++] = e->to;
            }
        }
    }
    int ok = D->level[t] >= 0;
    free(q);
    return ok;
}

static int dfs(Dinic *D, int u, int t, int f) {
    if (u == t) return f;
    for (int *i = &D->it[u]; *i < D->g[u].sz; (*i)++) {
        Edge *e = &D->g[u].e[*i];
        if (e->cap <= 0 || D->level[u] + 1 != D->level[e->to]) continue;
        int ret = dfs(D, e->to, t, f < e->cap ? f : e->cap);
        if (ret > 0) {
            e->cap -= ret;
            D->g[e->to].e[e->rev].cap += ret;
            return ret;
        }
    }
    return 0;
}

static ll maxflow(Dinic *D, int s, int t) {
    ll flow = 0;
    while (bfs(D, s, t)) {
        for (int i = 1; i <= D->n; i++) D->it[i] = 0;
        while (1) {
            int f = dfs(D, s, t, 1e9);
