def bfs(graph, source, sink, parent):
    visited = set([source])
    queue = deque([source])
    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if v not in visited and graph[u][v] > 0:
                visited.add(v)
                parent[v] = u
                if v == sink:
                    return True
                queue.append(v)
    return False

def max_flow(graph, source, sink):
    parent = {}
    max_flow_val = 0
    g = defaultdict(lambda: defaultdict(int))
    for u in graph:
        for v in graph[u]:
            g[u][v] += graph[u][v]

    while bfs(g, source, sink, parent):
        path_flow = float('inf')
        s = sink
        while s != source:
            u = parent[s]
            path_flow = min(path_flow, g[u][s])
            s = parent[s]
        max_flow_val += path_flow
        v = sink
        while v != source:
            u = parent[v]
            g[u][v] -= path_flow
            g[v][u] += path_flow
            v = parent[v]
        parent = {}
    return max_flow_val

