                edgeMap.put(k, e);
            }
            Integer st = start.get(k);
            if (st == null) {
                start.put(k, i);
            } else {
                if (st <= i - 1) seg.add(1, 1, Q, st, i - 1, e);
                start.remove(k);
            }
        }

        for (Map.Entry<Long, Integer> en : start.entrySet()) {
            int st = en.getValue();
            if (st <= Q) seg.add(1, 1, Q, st, Q, edgeMap.get(en.getKey()));
        }

        ans = new int[Q + 1];
        dsu = new RollbackDSU(N);
        dfs(1, 1, Q);

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= Q; i++) sb.append(ans[i]).append('\n');
        System.out.print(sb.toString());
    }
}
